const CHUNK=196608,LIMIT=80*1024*1024;
const waiting=new Map();let initialized=false;
export const isAndroidApp=()=>typeof window.WaraqaAndroid?.postMessage==='function';
export function initAndroidBridge(){if(!isAndroidApp()||initialized)return;initialized=true;window.WaraqaAndroid.onmessage=event=>{let response;try{response=JSON.parse(event.data);}catch{return;}const pending=waiting.get(response.requestId);if(!pending)return;waiting.delete(response.requestId);clearTimeout(pending.timer);if(response.ok)pending.resolve(response.value);else pending.reject(response.error==='cancelled'?new DOMException('cancelled','AbortError'):Error(response.error||'Native operation failed'));};
 Object.defineProperty(navigator,'canShare',{configurable:true,value:data=>Array.isArray(data?.files)&&data.files.length===1&&data.files[0] instanceof Blob&&data.files[0].size<=LIMIT});
 Object.defineProperty(navigator,'share',{configurable:true,value:async data=>{if(!navigator.canShare(data))throw new TypeError('Share one file at a time');const file=data.files[0];await exportAndroidFile(file,file.name||'waraqa-file','share');}});
}
export function nativeRequest(action,values={},timeout=60000){initAndroidBridge();if(!isAndroidApp())return Promise.reject(Error('Android app is unavailable'));const requestId=crypto.randomUUID();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{waiting.delete(requestId);reject(Error('Android operation timed out'));},timeout);waiting.set(requestId,{resolve,reject,timer});try{window.WaraqaAndroid.postMessage(JSON.stringify({...values,action,requestId}));}catch(error){clearTimeout(timer);waiting.delete(requestId);reject(error);}});}
function decode64(value){return Uint8Array.from(atob(value),c=>c.charCodeAt(0));}
function encode64(value){let text='';for(let i=0;i<value.length;i+=32768)text+=String.fromCharCode(...value.subarray(i,i+32768));return btoa(text);}
export async function nativeIncoming(preferredId){const batches=await nativeRequest('list');if(!Array.isArray(batches))throw Error('Invalid native inbox');const batch=preferredId?batches.find(b=>b.id===preferredId):batches[0];if(!batch)return null;return batch;}
export async function nativeFiles(batch){if(!Array.isArray(batch.files)||!batch.files.length||batch.files.length>80||batch.files.reduce((n,f)=>n+f.size,0)>LIMIT)throw Error('Invalid shared files');const files=[];for(const file of batch.files){if(!Number.isSafeInteger(file.size)||file.size<1||file.size>LIMIT||typeof file.name!=='string'||typeof file.type!=='string')throw Error('Invalid shared file');const pieces=[];for(let offset=0;offset<file.size;offset+=CHUNK){const expected=Math.min(CHUNK,file.size-offset),piece=decode64(await nativeRequest('read',{batchId:batch.id,fileId:file.id,offset,length:expected}));if(piece.length!==expected)throw Error('Shared file is incomplete');pieces.push(piece);}files.push({name:file.name,type:file.type,blob:new Blob(pieces,{type:file.type})});}return files;}
export const deleteNativeIncoming=id=>nativeRequest('delete',{batchId:id});
// Serializing exports avoids overlapping save-location pickers.
let exportQueue=Promise.resolve();
export function exportAndroidFile(blob,name,mode='save'){const task=exportQueue.catch(()=>{}).then(async()=>{if(!(blob instanceof Blob)||blob.size>LIMIT)throw Error('Android export limit is 80 MB');const token=await nativeRequest('beginExport',{name,type:blob.type||'application/octet-stream',size:blob.size});for(let offset=0;offset<blob.size;offset+=CHUNK){const bytes=new Uint8Array(await blob.slice(offset,offset+CHUNK).arrayBuffer());await nativeRequest('writeExport',{token,offset,data:encode64(bytes)});}return nativeRequest('finishExport',{token,mode},10*60*1000);});exportQueue=task;return task;}
